def axcat(a):
    if -30<=a<=90: return 'NORMAL'
    if -90<=a<-30: return 'LEFT'
    if 90<a<=180: return 'RIGHT'
    return 'EXTREME'
def rhythm(e): return 'AF' if e in AF else 'SINUS'

rows=[]
